const rows = $input.all().map(i=>i.json).filter(r=>r.service_code);
if(rows.length!==10 || new Set(rows.map(r=>r.service_code)).size!==10) throw new Error('Expected exactly 10 services');
for(const r of rows) if(r.environment!=='TEST'||r.pricebook_version!=='TEST-2026-11-v1'||r.embedding_dimensions!==1536||r.embedding_model!=='text-embedding-3-small') throw new Error('Invalid pricebook configuration');
return [{json:{rows, model:'text-embedding-3-small', dimensions:1536,input:rows.map(r=>r.service_code+' — '+r.title+'\n'+r.description)}}];

const source=$('Prepare Documents').first().json;
const data=$json.data;
if(!Array.isArray(data)||data.length!==source.rows.length) throw new Error('Embedding count mismatch');
const seen=new Set();
for(const d of data){if(!Number.isInteger(d.index)||d.index<0||d.index>=source.rows.length||seen.has(d.index)||!Array.isArray(d.embedding)||d.embedding.length!==1536||d.embedding.some(x=>!Number.isFinite(x))) throw new Error('Invalid embedding'); seen.add(d.index);}
return [{json:{points:data.map(d=>{const r=source.rows[d.index];return {id:r.point_id,vector:d.embedding,payload:{service_code:r.service_code,pricebook_version:r.pricebook_version,environment:'TEST',language:'sk',title:r.title,text:source.input[d.index],embedding_model:source.model,embedding_dimensions:1536,price_source:'PostgreSQL:wdfox_test.pricebook_items'}};})}}];

const status=Number($json.statusCode);const message=JSON.stringify($json.body||{});
if(!((status>=200&&status<300)||((status===409||status===400)&&/already exists/i.test(message)))) throw new Error('Qdrant collection creation failed; inspect credentials/network and response');
return [{json:{ok:true}}];

const v=$json.result?.config?.params?.vectors;
if(!v||v.size!==1536||v.distance!=='Cosine') throw new Error('Collection vector configuration mismatch; do not delete an existing collection');
return [{json:$('Validate Embeddings').first().json}];

const rows=$input.all().map(i=>i.json).filter(r=>r.service_code);
if(rows.length!==10) throw new Error('Index status count mismatch');
return [{json:{ok:true,environment:'TEST',pricebook_version:'TEST-2026-11-v1',indexed_services:rows.length,collection:'wdfox_pricebook_test',model:'text-embedding-3-small',dimensions:1536,prices_from:'PostgreSQL',billing_enabled:false,production_touched:false,note:'Import only. Semantic retrieval and customer quotations require a separate workflow.',services:rows}}];
